#define LOGE(...) fprintf(stderr, __VA_ARGS__)
#define V4L2_BUF_FLAG_KEYFRAME 8
const int env_debug_encoder = 0;
namespace capnp { using byte = uint8_t; }
namespace kj {
template<class T> struct ArrayPtr { T *pointer; size_t length; };
template<class T> ArrayPtr<T> arrayPtr(T *pointer, size_t length) { return {pointer, length}; }
}
namespace cereal { struct EncodeIndex { enum class Type { QCAMERA_H264, BIG_BOX_LOSSLESS }; }; }
struct VisionIpcBufExtra { uint32_t frame_id; uint64_t timestamp_sof, timestamp_eof; };
struct VisionBuf { uint8_t *y, *uv; size_t width, height, stride; };
struct EncoderSettings { cereal::EncodeIndex::Type encode_type; };
struct EncoderInfo {
  const char *publish_name = "fixture";
  int width, height;
  int fps = 20;
  EncoderSettings settings;
  EncoderSettings get_settings(int) const { return settings; }
};
static std::filesystem::path directory;
static std::ofstream trace;
static unsigned packet_number = 0;
static void save_packet(const uint8_t *data, size_t size) {
  std::ofstream output(directory / ("packet-" + std::to_string(packet_number) + ".bin"), std::ios::binary);
  output.write(reinterpret_cast<const char *>(data), size);
}
class VideoEncoder {
public:
  VideoEncoder(const EncoderInfo &info, int width, int height)
      : in_width(width), in_height(height), out_width(info.width), out_height(info.height), encoder_info(info) {}
  virtual ~VideoEncoder() = default;
  void publisher_publish(int segment, uint32_t index, VisionIpcBufExtra &extra, unsigned flags,
      kj::ArrayPtr<capnp::byte>, kj::ArrayPtr<capnp::byte> data) {
    save_packet(data.pointer, data.length);
    trace << "P\t" << packet_number++ << '\t' << segment << '\t' << index << '\t' << extra.frame_id
          << '\t' << extra.timestamp_sof << '\t' << extra.timestamp_eof << '\t' << flags << '\t' << data.length << '\n';
  }
protected:
  int in_width, in_height, out_width, out_height;
  const EncoderInfo encoder_info;
};
struct ThumbnailMessage {
  uint32_t frame_id = 0;
  uint64_t timestamp = 0;
  kj::ArrayPtr<uint8_t> bytes{};
  void setFrameId(uint32_t value) { frame_id = value; }
  void setTimestampEof(uint64_t value) { timestamp = value; }
  void setThumbnail(kj::ArrayPtr<uint8_t> value) { bytes = value; }
};
struct ThumbnailBuilder {
  ThumbnailMessage *message;
  void setFrameId(uint32_t value) { message->setFrameId(value); }
  void setTimestampEof(uint64_t value) { message->setTimestampEof(value); }
  void setThumbnail(kj::ArrayPtr<uint8_t> value) { message->setThumbnail(value); }
};
struct EventBuilder { ThumbnailMessage *message; ThumbnailBuilder initThumbnail() { return {message}; } };
struct MessageBuilder { ThumbnailMessage message; EventBuilder initEvent() { return {&message}; } };
struct PubMaster {
  explicit PubMaster(const std::vector<const char *> &) {}
  void send(const char *, MessageBuilder &message) {
    auto &thumbnail = message.message;
    save_packet(thumbnail.bytes.pointer, thumbnail.bytes.length);
    trace << "J\t" << packet_number++ << '\t' << thumbnail.frame_id << '\t' << thumbnail.timestamp << '\t' << thumbnail.bytes.length << '\n';
  }
};

class FfmpegEncoder : public VideoEncoder {
public:
  FfmpegEncoder(const EncoderInfo &encoder_info, int in_width, int in_height);
  ~FfmpegEncoder();
  int encode_frame(VisionBuf* buf, VisionIpcBufExtra *extra);
  void encoder_open();
  void encoder_close();

private:
  int segment_num = -1;
  int counter = 0;
  bool is_open = false;

  AVCodecContext *codec_ctx;
  AVFrame *frame = NULL;
  std::vector<uint8_t> convert_buf;
  std::vector<uint8_t> downscale_buf;
};

class JpegEncoder {
public:
  JpegEncoder(const std::string &pusblish_name, int width, int height);
  ~JpegEncoder();
  void pushThumbnail(VisionBuf *buf, const VisionIpcBufExtra &extra);

private:
  void generateThumbnail(const uint8_t *y, const uint8_t *uv, int width, int height, int stride);
  void compressToJpeg(uint8_t *y_plane, uint8_t *u_plane, uint8_t *v_plane);

  int thumbnail_width;
  int thumbnail_height;
  std::string publish_name;
  std::vector<uint8_t> yuv_buffer;
  std::unique_ptr<PubMaster> pm;

  // JPEG output buffer
  unsigned char* out_buffer = nullptr;
  unsigned long out_size = 0;
};

FfmpegEncoder::FfmpegEncoder(const EncoderInfo &encoder_info, int in_width, int in_height)
    : VideoEncoder(encoder_info, in_width, in_height) {
  frame = av_frame_alloc();
  assert(frame);
  frame->format = AV_PIX_FMT_YUV420P;
  frame->width = out_width;
  frame->height = out_height;
  frame->linesize[0] = out_width;
  frame->linesize[1] = out_width/2;
  frame->linesize[2] = out_width/2;

  convert_buf.resize(in_width * in_height * 3 / 2);

  if (in_width != out_width || in_height != out_height) {
    downscale_buf.resize(out_width * out_height * 3 / 2);
  }
}

FfmpegEncoder::~FfmpegEncoder() {
  encoder_close();
  av_frame_free(&frame);
}

void FfmpegEncoder::encoder_open() {
  auto codec_id = encoder_info.get_settings(in_width).encode_type == cereal::EncodeIndex::Type::QCAMERA_H264
                      ? AV_CODEC_ID_H264
                      : AV_CODEC_ID_FFVHUFF;
  const AVCodec *codec = avcodec_find_encoder(codec_id);

  this->codec_ctx = avcodec_alloc_context3(codec);
  assert(this->codec_ctx);
  this->codec_ctx->width = frame->width;
  this->codec_ctx->height = frame->height;
  this->codec_ctx->pix_fmt = AV_PIX_FMT_YUV420P;
  this->codec_ctx->time_base = (AVRational){ 1, encoder_info.fps };
  int err = avcodec_open2(this->codec_ctx, codec, NULL);
  assert(err >= 0);

  is_open = true;
  segment_num++;
  counter = 0;
}

void FfmpegEncoder::encoder_close() {
  if (!is_open) return;

  avcodec_free_context(&codec_ctx);
  is_open = false;
}

int FfmpegEncoder::encode_frame(VisionBuf* buf, VisionIpcBufExtra *extra) {
  assert(buf->width == this->in_width);
  assert(buf->height == this->in_height);

  uint8_t *cy = convert_buf.data();
  uint8_t *cu = cy + in_width * in_height;
  uint8_t *cv = cu + (in_width / 2) * (in_height / 2);
  libyuv::NV12ToI420(buf->y, buf->stride,
                     buf->uv, buf->stride,
                     cy, in_width,
                     cu, in_width/2,
                     cv, in_width/2,
                     in_width, in_height);

  if (downscale_buf.size() > 0) {
    uint8_t *out_y = downscale_buf.data();
    uint8_t *out_u = out_y + frame->width * frame->height;
    uint8_t *out_v = out_u + (frame->width / 2) * (frame->height / 2);
    libyuv::I420Scale(cy, in_width,
                      cu, in_width/2,
                      cv, in_width/2,
                      in_width, in_height,
                      out_y, frame->width,
                      out_u, frame->width/2,
                      out_v, frame->width/2,
                      frame->width, frame->height,
                      libyuv::kFilterNone);
    frame->data[0] = out_y;
    frame->data[1] = out_u;
    frame->data[2] = out_v;
  } else {
    frame->data[0] = cy;
    frame->data[1] = cu;
    frame->data[2] = cv;
  }
  frame->pts = counter*50*1000; // 50ms per frame

  int ret = counter;

  int err = avcodec_send_frame(this->codec_ctx, frame);
  if (err < 0) {
    LOGE("avcodec_send_frame error %d", err);
    ret = -1;
  }

  AVPacket pkt = {};
  pkt.data = NULL;
  pkt.size = 0;
  while (ret >= 0) {
    err = avcodec_receive_packet(this->codec_ctx, &pkt);
    if (err == AVERROR_EOF) {
      break;
    } else if (err == AVERROR(EAGAIN)) {
      // Encoder might need a few frames on startup to get started. Keep going
      ret = 0;
      break;
    } else if (err < 0) {
      LOGE("avcodec_receive_packet error %d", err);
      ret = -1;
      break;
    }

    if (env_debug_encoder) {
      printf("%20s got %8d bytes flags %8x idx %4d id %8d\n", encoder_info.publish_name, pkt.size, pkt.flags, counter, extra->frame_id);
    }

    publisher_publish(segment_num, counter, *extra,
      (pkt.flags & AV_PKT_FLAG_KEY) ? V4L2_BUF_FLAG_KEYFRAME : 0,
      kj::arrayPtr<capnp::byte>(pkt.data, (size_t)0), // TODO: get the header
      kj::arrayPtr<capnp::byte>(pkt.data, pkt.size));

    counter++;
  }
  av_packet_unref(&pkt);
  return ret;
}

JpegEncoder::JpegEncoder(const std::string &pusblish_name, int width, int height)
    : publish_name(pusblish_name), thumbnail_width(width), thumbnail_height(height) {
  yuv_buffer.resize((thumbnail_width * ((thumbnail_height + 15) & ~15) * 3) / 2);
  pm = std::make_unique<PubMaster>(std::vector{pusblish_name.c_str()});
}

JpegEncoder::~JpegEncoder() {
  if (out_buffer) {
    free(out_buffer);
  }
}

void JpegEncoder::pushThumbnail(VisionBuf *buf, const VisionIpcBufExtra &extra) {
  generateThumbnail(buf->y, buf->uv, buf->width, buf->height, buf->stride);

  MessageBuilder msg;
  auto thumbnaild = msg.initEvent().initThumbnail();
  thumbnaild.setFrameId(extra.frame_id);
  thumbnaild.setTimestampEof(extra.timestamp_eof);
  thumbnaild.setThumbnail({out_buffer, out_size});

  pm->send(publish_name.c_str(), msg);
}

void JpegEncoder::generateThumbnail(const uint8_t *y_addr, const uint8_t *uv_addr, int width, int height, int stride) {
  int downscale = width / thumbnail_width;
  assert(downscale * thumbnail_height == height);

  // make the buffer big enough. jpeg_write_raw_data requires 16-pixels aligned height to be used.
  uint8_t *y_plane = yuv_buffer.data();
  uint8_t *u_plane = y_plane + thumbnail_width * thumbnail_height;
  uint8_t *v_plane = u_plane + (thumbnail_width * thumbnail_height) / 4;
  {
    // subsampled conversion from nv12 to yuv
    for (int hy = 0; hy < thumbnail_height / 2; hy++) {
      for (int hx = 0; hx < thumbnail_width / 2; hx++) {
        int ix = hx * downscale + (downscale - 1) / 2;
        int iy = hy * downscale + (downscale - 1) / 2;
        y_plane[(hy * 2 + 0) * thumbnail_width + (hx * 2 + 0)] = y_addr[(iy * 2 + 0) * stride + ix * 2 + 0];
        y_plane[(hy * 2 + 0) * thumbnail_width + (hx * 2 + 1)] = y_addr[(iy * 2 + 0) * stride + ix * 2 + 1];
        y_plane[(hy * 2 + 1) * thumbnail_width + (hx * 2 + 0)] = y_addr[(iy * 2 + 1) * stride + ix * 2 + 0];
        y_plane[(hy * 2 + 1) * thumbnail_width + (hx * 2 + 1)] = y_addr[(iy * 2 + 1) * stride + ix * 2 + 1];
        u_plane[hy * thumbnail_width / 2 + hx] = uv_addr[iy * stride + ix * 2 + 0];
        v_plane[hy * thumbnail_width / 2 + hx] = uv_addr[iy * stride + ix * 2 + 1];
      }
    }
  }

  compressToJpeg(y_plane, u_plane, v_plane);
}

void JpegEncoder::compressToJpeg(uint8_t *y_plane, uint8_t *u_plane, uint8_t *v_plane) {
  struct jpeg_compress_struct cinfo;
  struct jpeg_error_mgr jerr;
  cinfo.err = jpeg_std_error(&jerr);
  jpeg_create_compress(&cinfo);

  if (out_buffer) {
    free(out_buffer);
    out_buffer = nullptr;
    out_size = 0;
  }
  jpeg_mem_dest(&cinfo, &out_buffer, &out_size);

  cinfo.image_width = thumbnail_width;
  cinfo.image_height = thumbnail_height;
  cinfo.input_components = 3;

  jpeg_set_defaults(&cinfo);
  jpeg_set_colorspace(&cinfo, JCS_YCbCr);
  // configure sampling factors for yuv420.
  cinfo.comp_info[0].h_samp_factor = 2;  // Y
  cinfo.comp_info[0].v_samp_factor = 2;
  cinfo.comp_info[1].h_samp_factor = 1;  // U
  cinfo.comp_info[1].v_samp_factor = 1;
  cinfo.comp_info[2].h_samp_factor = 1;  // V
  cinfo.comp_info[2].v_samp_factor = 1;
  cinfo.raw_data_in = TRUE;

  jpeg_set_quality(&cinfo, 50, TRUE);
  jpeg_start_compress(&cinfo, TRUE);

  JSAMPROW y[16], u[8], v[8];
  JSAMPARRAY planes[3]{y, u, v};

  for (int line = 0; line < cinfo.image_height; line += 16) {
    for (int i = 0; i < 16; ++i) {
      y[i] = y_plane + (line + i) * cinfo.image_width;
      if (i % 2 == 0) {
        int offset = (cinfo.image_width / 2) * ((i + line) / 2);
        u[i / 2] = u_plane + offset;
        v[i / 2] = v_plane + offset;
      }
    }
    jpeg_write_raw_data(&cinfo, planes, 16);
  }

  jpeg_finish_compress(&cinfo);
  jpeg_destroy_compress(&cinfo);
}

